using System;using System.Collections.Generic;public class Solution{List<IList<int>>o=new();void F(int[]a,int st,int r,List<int>v){if(r==0){o.Add(new List<int>(v));return;}for(int i=st;i<a.Length&&a[i]<=r;i++){if(i>st&&a[i]==a[i-1])continue;v.Add(a[i]);F(a,i+1,r-a[i],v);v.RemoveAt(v.Count-1);}}public IList<IList<int>> CombinationSum2(int[]a,int t){Array.Sort(a);F(a,0,t,new List<int>());return o;}}
